export function retentionLedger(records,releases=[],companyId){
 const items=Object.values(records).filter(r=>r.reviewed&&r.companyId===companyId&&Number.isSafeInteger(r.retentionCents)&&r.retentionCents>0).sort((a,b)=>(a.paymentDate||a.reviewedDate||'').localeCompare(b.paymentDate||b.reviewedDate||'')||String(a.invoiceNumber||'').localeCompare(String(b.invoiceNumber||'')));
 const projects=[...new Set([...items.map(r=>r.project),...releases.filter(r=>r.companyId===companyId&&r.status!=='cancelled').map(r=>r.project)])].sort();
 return projects.map(project=>{const rows=items.filter(r=>r.project===project),payments=releases.filter(r=>r.companyId===companyId&&r.project===project&&r.status!=='cancelled'),withheldCents=rows.reduce((s,r)=>s+r.retentionCents,0),paidCents=payments.filter(r=>r.status==='paid').reduce((s,r)=>s+r.amountCents,0),plannedCents=payments.filter(r=>r.status==='planned').reduce((s,r)=>s+r.amountCents,0);return{project,rows,payments,withheldCents,paidCents,plannedCents,openCents:withheldCents-paidCents,availableCents:withheldCents-paidCents-plannedCents};});
}
export function validateRelease(amountCents,availableCents){if(!Number.isSafeInteger(amountCents)||amountCents<=0)throw Error('Bitte einen positiven Auszahlungsbetrag eingeben.');if(amountCents>availableCents)throw Error('Der Betrag übersteigt den noch verfügbaren Einbehalt.');return amountCents;}
export async function retentionProtocol(companyName,release){
 const lib=await import('./vendor/pdf-lib.min.mjs'),{drawPaymentStamp}=await import('./stamp.mjs'),pdf=await lib.PDFDocument.create(),font=await pdf.embedFont(lib.StandardFonts.Helvetica),bold=await pdf.embedFont(lib.StandardFonts.HelveticaBold);const clean=s=>String(s??'').replace(/[–—−]/g,'-').replace(/[^\x20-\x7e\u00a0-\u00ff€]/g,'?'),fmt=c=>(c/100).toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2})+' EUR';let page,y,index=0;
 const text=(value,x,yy,size=9,strong=false,max=500)=>{const f=strong?bold:font;let s=clean(value);while(s.length>3&&f.widthOfTextAtSize(s,size)>max)s=s.slice(0,-4)+'...';page.drawText(s,{x,y:yy,size,font:f});};
 const newPage=()=>{page=pdf.addPage([595.28,841.89]);index++;y=792;text('DaSo | Sicherheitseinbehalt',35,y,16,true);y-=25;text(companyName,35,y,11,true);y-=19;text('Projekt: '+release.project,35,y,10);y-=18;text('Auszahlungsprotokoll | '+(release.status==='paid'?'Ausgezahlt':'Vorbereitet')+' | '+release.paymentDate,35,y,9);y-=30;text('Rechnung',35,y,9,true);text('Datum',220,y,9,true);text('Einbehalt',325,y,9,true);text('Kumuliert',445,y,9,true);y-=18;};
 newPage();let cumulative=0;for(const r of release.items||[]){if(y<(index===1?225:65))newPage();cumulative+=r.retentionCents;text(r.invoiceNumber||r.fileName||'ohne Nummer',35,y,9,false,175);text(r.paymentDate||r.reviewedDate||'offen',220,y,9,false,95);text(fmt(r.retentionCents),325,y,9,false,110);text(fmt(cumulative),445,y,9,false,115);y-=20;}
 if(y<(index===1?265:105))newPage();y-=12;text('Einbehalte gesamt: '+fmt(release.withheldCents),35,y,10,true);y-=19;text('Bisher ausgezahlt: '+fmt(release.paidBeforeCents),35,y);y-=19;text('Diese Auszahlung: '+fmt(release.amountCents),35,y,10,true);y-=19;text('Danach verbleibend: '+fmt(release.openAfterCents),35,y);y-=19;if(release.acceptanceDate)text('Abnahme am: '+release.acceptanceDate,35,y);if(release.note){y-=19;text('Notiz: '+release.note,35,y,9,false,520);}
 await drawPaymentStamp(pdf,pdf.getPage(0),{x:279,y:30,width:300,height:150},{kind:'retention-release',reviewer:release.reviewer,paymentDate:release.paymentDate,paid:release.status==='paid',paymentCents:release.amountCents,withheldCents:release.withheldCents,paidBeforeCents:release.paidBeforeCents,openAfterCents:release.openAfterCents},{},'EINBEHALT FREIGEGEBEN');
 for(let i=0;i<pdf.getPageCount();i++)pdf.getPage(i).drawText('DaSo | Auszahlungsprotokoll | '+(i+1)+' / '+pdf.getPageCount(),{x:35,y:15,size:7,font});return pdf.save();
}
